// Motor de sonido de la página (../index.html), copiado tal cual salvo beep(), que aquí no depende de los
// controles de la página. Si cambias el sonido en la página, vuelve a copiarlo aquí.
let AC,GN,HB,HG,B1,B2,T1,T2,SRC;
const SND='data:audio/mpeg;base64,';
/* Sonido. Suena como sonaría ese viento: el dato no se lleva a un ritmo ni al volumen, sino a lo que cambia
   en el sonido real del viento cuando aumenta su velocidad U. Las frecuencias son proporcionales a U (en m/s),
   como en el viento real: doblar el viento sube el sonido una octava. Tres capas:
   - Fondo: la grabación de viento, igual en todos los vientos; le da la textura de viento real.
   - Soplo: ruido blanco por un pasabanda ancho (Q 0,7) centrado en 30·U Hz: 385 Hz a 25 kt (un soplido sordo),
     2.850 Hz a 185 kt (el siseo de la lluvia y la espuma arrastradas). Su peso sube con el viento.
   - Silbido (tonos eólicos): un obstáculo de diámetro d en un viento U silba a f = St·U/d, con St ≈ 0,2
     (Strouhal, 1878). Ruido blanco por dos bandas angostas (Q 30), para cables de ~1 cm (20·U Hz: 260 Hz a
     25 kt, 1.900 Hz a 185 kt) y ramas de ~2,5 cm (8·U Hz). El ruido que pasa una banda angosta sale como un
     tono que tiembla solo, como el silbido real; no se añade ningún pulso. Su peso también sube con el viento.
   Los pesos van de 0 a ~19 kt (10 m/s) a pleno a ~117 kt (60 m/s). Se usa ruido sintético y no la grabación
   para el soplo y el silbido porque la grabación casi no tiene energía sobre 1 kHz: filtrada, una categoría 5
   no sonaba más aguda que una tormenta tropical.
   Volumen fijo: más brillo suena más fuerte con la misma energía, así que la ganancia se corrige con LN, la
   sonoridad medida (ponderación K, ITU-R BS.1770) de la propia cadena cada 5 kt entre 20 y 190 kt; queda igual
   en todos los vientos (ver scripts/verificar_sonido.html). */
const MS=v=>Math.max(v,20)*.5144,LN=[3.36,3.36,3.37,3.4,3.42,3.47,3.54,3.64,3.75,3.88,4.08,4.24,4.5,4.78,5.06,5.35,5.66,5.99,6.37,6.77,6.94,7.05,7.15,7.24,7.37,7.46,7.62,7.74,7.87,7.96,8.05,8.15,8.26,8.35,8.42],SK=.6,TK=2.75;
const lnd=v=>{const x=(Math.min(Math.max(v,20),190)-20)/5,i=Math.max(0,Math.min(LN.length-2,Math.floor(x)));return LN.length<2?0:LN[i]+(LN[i+1]-LN[i])*(x-i)};
const SON=v=>{const u=MS(v);return{fs:30*u,f1:20*u,f2:8*u,m:Math.min(1,Math.max(0,(u-10)/50))}};
function beep(v){if(!AC||!GN)return;const t=AC.currentTime;if(!v){GN.gain.setTargetAtTime(0,t,.08);return}
const p=SON(v);HB.frequency.setTargetAtTime(p.fs,t,.12);B1.frequency.setTargetAtTime(p.f1,t,.12);B2.frequency.setTargetAtTime(p.f2,t,.12);
HG.gain.setTargetAtTime(p.m*SK,t,.12);T1.gain.setTargetAtTime(p.m*TK,t,.12);T2.gain.setTargetAtTime(p.m*TK*.6,t,.12);GN.gain.setTargetAtTime(.7*Math.pow(10,-lnd(v)/20),t,.12)}
function initAudio(){if(AC)return AC.resume();AC=new(window.AudioContext||window.webkitAudioContext)();
const gan=g=>{const n=AC.createGain();n.gain.value=g;return n},flt=(y,f,q)=>{const b=AC.createBiquadFilter();b.type=y;b.frequency.value=f;b.Q.value=q;return b};
HB=flt('bandpass',400,.7);B1=flt('bandpass',300,30);B2=flt('bandpass',120,30);HG=gan(0);T1=gan(0);T2=gan(0);GN=gan(0);
HB.connect(HG);HG.connect(GN);B1.connect(T1);T1.connect(GN);B2.connect(T2);T2.connect(GN);GN.connect(AC.destination);
// Ruido blanco: 4 s en bucle, con semilla fija para que suene igual en cada visita.
const nb=AC.createBuffer(1,AC.sampleRate*4,AC.sampleRate),nd=nb.getChannelData(0);let sd=1;for(let i=0;i<nd.length;i++){sd=(sd*16807)%2147483647;nd[i]=sd/1073741823.5-1}
const NZ=AC.createBufferSource();NZ.buffer=nb;NZ.loop=true;[HB,B1,B2].forEach(n=>NZ.connect(n));NZ.start();
const bin=atob(SND.split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
AC.decodeAudioData(u.buffer,buf=>{SRC=AC.createBufferSource();SRC.buffer=buf;SRC.loop=true;SRC.connect(GN);SRC.start()},()=>{})}
